"""Device scanner — reports hardware info at benchmark startup."""
import logging
import os
import platform

logger = logging.getLogger(__name__)


def scan_devices() -> dict:
    """Scan and log available hardware.

    Returns
    -------
    dict
        Dictionary with keys: cpu, memory_gb, gpu, cuda_available, cuda_version.
    """
    info = {
        "platform": platform.platform(),
        "python": platform.python_version(),
        "cpu": _get_cpu_info(),
        "cpu_cores_physical": _get_physical_cores(),
        "cpu_cores_logical": os.cpu_count(),
        "memory_gb": _get_memory_gb(),
        "cuda_available": False,
        "cuda_version": None,
        "gpu": None,
        "gpu_memory_gb": None,
    }

    # Check CUDA / GPU via CuPy
    try:
        import cupy as cp
        info["cuda_available"] = True
        info["cuda_version"] = cp.cuda.runtime.runtimeGetVersion()
        device = cp.cuda.Device(0)
        free, total = device.mem_info
        info["gpu_memory_gb"] = round(total / (1024 ** 3), 2)
        # Get device name
        try:
            props = cp.cuda.runtime.getDeviceProperties(0)
            info["gpu"] = props.get("name", str(device))
        except Exception:
            info["gpu"] = f"GPU {device.id} (compute {device.compute_capability})"
    except (ImportError, Exception) as e:
        logger.debug(f"CuPy/CUDA not available: {e}")

    _log_info(info)
    return info


def format_device_info(info: dict) -> str:
    """Format device info as a comma-delimited string for plot footers.

    Parameters
    ----------
    info : dict
        Dictionary returned by scan_devices().

    Returns
    -------
    str
        Comma-delimited summary string.
    """
    parts = [info["cpu"], f"{info['cpu_cores_logical']} logical cores", f"{info['memory_gb']} GB RAM"]
    if info["cuda_available"]:
        cuda_ver = info["cuda_version"]
        major = cuda_ver // 1000
        minor = (cuda_ver % 1000) // 10
        parts.append(f"CUDA {major}.{minor}")
        if info["gpu"]:
            gpu_name = info["gpu"]
            if isinstance(gpu_name, bytes):
                gpu_name = gpu_name.decode("utf-8", errors="replace")
            parts.append(gpu_name)
        if info["gpu_memory_gb"]:
            parts.append(f"{info['gpu_memory_gb']} GB VRAM")
    else:
        parts.append("No CUDA")
    return ", ".join(parts)


def _get_cpu_info() -> str:
    """Get CPU model name."""
    try:
        with open("/proc/cpuinfo", "r") as f:
            for line in f:
                if line.startswith("model name"):
                    return line.split(":")[1].strip()
    except (FileNotFoundError, PermissionError):
        pass
    return platform.processor() or "unknown"


def _get_physical_cores() -> int:
    """Get number of physical CPU cores."""
    try:
        import multiprocessing
        return multiprocessing.cpu_count()
    except Exception:
        return os.cpu_count() or 0


def _get_memory_gb() -> float:
    """Get total system RAM in GB."""
    try:
        with open("/proc/meminfo", "r") as f:
            for line in f:
                if line.startswith("MemTotal"):
                    kb = int(line.split()[1])
                    return round(kb / (1024 ** 2), 2)
    except (FileNotFoundError, PermissionError):
        pass
    return 0.0


def _log_info(info: dict):
    """Log hardware info."""
    logger.info("=" * 60)
    logger.info("DEVICE SCAN")
    logger.info("=" * 60)
    logger.info(f"  Platform:    {info['platform']}")
    logger.info(f"  Python:      {info['python']}")
    logger.info(f"  CPU:         {info['cpu']}")
    logger.info(f"  CPU cores:   {info['cpu_cores_logical']} logical")
    logger.info(f"  RAM:         {info['memory_gb']} GB")
    if info["cuda_available"]:
        cuda_ver = info["cuda_version"]
        major = cuda_ver // 1000
        minor = (cuda_ver % 1000) // 10
        logger.info(f"  CUDA:        {major}.{minor}")
        logger.info(f"  GPU:         {info['gpu']}")
        logger.info(f"  GPU Memory:  {info['gpu_memory_gb']} GB")
    else:
        logger.info("  CUDA:        NOT AVAILABLE")
    logger.info("=" * 60)
